import React from 'react';

import {
  OverlaysProps,
  OverlayHandlers,
} from '../../../../core/types/overlays.js';
import { useSetState } from '../../../hooks/store/selectors.js';

export const useHistogramMouseEventHandlers = (): OverlayHandlers => {
  const setState = useSetState();

  const mouseMoveHandler = (
    event: React.MouseEvent,
    overlaysState: OverlaysProps,
  ) => {
    setState((prev) => ({
      ...prev,
      overlays: {
        ...prev.overlays,
        visibleTooltip:
          overlaysState.isInChartBounds || prev.overlays.pinnedTooltip,
      },
    }));
  };

  const mouseLeave = () => {
    setState((prev) => ({
      ...prev,
      overlays: {
        ...prev.overlays,
        visibleTooltip: prev.overlays.pinnedTooltip,
      },
    }));
  };

  return {
    move: mouseMoveHandler,
    leave: mouseLeave,
  };
};
